This architecture represents a production-ready QA Automation framework built on **WebdriverIO**, **Appium**, and **TypeScript**. It utilizes the **Page Object Model (POM)** pattern to ensure high maintainability, scalability, and code reusability. The framework is designed for cross-platform mobile test automation with a modular structure that facilitates easy integration into CI/CD pipelines.

---

### 📂 Folder Structure

```text
├── config/
│   └── wdio.conf.ts
├── pageobjects/
│   ├── base.page.ts
│   └── flight-search.page.ts
├── tests/
│   └── flight-search.spec.ts
├── .env
├── package.json
└── tsconfig.json
```

---

### --- Configuration & Dependencies

#### `package.json`
```json
{
  "name": "appium-ts-automation",
  "version": "1.0.0",
  "devDependencies": {
    "@wdio/cli": "^8.29.0",
    "@wdio/mocha-framework": "^8.29.0",
    "@wdio/appium-service": "^8.29.0",
    "ts-node": "^10.9.2",
    "typescript": "^5.3.3"
  }
}
```

#### `tsconfig.json`
```json
{
  "compilerOptions": {
    "target": "ESNext",
    "module": "CommonJS",
    "moduleResolution": "node",
    "esModuleInterop": true,
    "strict": true,
    "skipLibCheck": true
  }
}
```

#### `config/wdio.conf.ts`
```typescript
export const config: WebdriverIO.Config = {
    runner: 'local',
    specs: ['../tests/**/*.spec.ts'],
    framework: 'mocha',
    services: ['appium'],
    capabilities: [{
        platformName: 'Android',
        'appium:automationName': 'UiAutomator2',
        'appium:deviceName': 'Android Emulator',
        'appium:app': '/path/to/your/app.apk'
    }],
    mochaOpts: { timeout: 60000 },
    autoCompileOpts: {
        autoCompile: true,
        tsNodeOpts: { project: 'tsconfig.json' }
    }
};
```

---

### --- Page Object Model (POM)

#### `pageobjects/base.page.ts`
```typescript
export default class BasePage {
    async pause(ms: number) { await browser.pause(ms); }
}
```

#### `pageobjects/flight-search.page.ts`
```typescript
import BasePage from './base.page';

class FlightSearchPage extends BasePage {
    get oneWayRadio() { return $('~radio_one_way'); }
    get originDropdown() { return $('~dropdown_origin'); }
    get destinationDropdown() { return $('~dropdown_destination'); }
    get datePicker() { return $('~date_picker'); }
    get passengerDropdown() { return $('~dropdown_passengers'); }
    get classDropdown() { return $('~dropdown_class'); }
    get searchBtn() { return $('~btn_search_flights'); }
    get flightResults() { return $('~flight_results_container'); }

    async performSearch(origin: string, dest: string, date: string, passengers: string, serviceClass: string) {
        await this.oneWayRadio.click();
        await this.originDropdown.selectByVisibleText(origin);
        await this.destinationDropdown.selectByVisibleText(dest);
        await this.datePicker.setValue(date);
        await this.passengerDropdown.selectByVisibleText(passengers);
        await this.classDropdown.selectByVisibleText(serviceClass);
        await this.searchBtn.click();
    }
}
export default new FlightSearchPage();
```

---

### --- Test Implementation

#### `tests/flight-search.spec.ts`
```typescript
import FlightSearchPage from '../pageobjects/flight-search.page';
import { expect } from 'chai';

describe('Flight Search Functionality', () => {

    // TC-TS-INPUTSOURCE-01-01: One-Way Flight Search
    it('Verify flight search execution with valid parameters', async () => {
        const testData = [
            { origin: 'Mumbai (BOM)', dest: 'New York (NYC)', date: '15-Oct-2026', pax: '1', class: 'Economy' },
            { origin: 'Mumbai (BOM)', dest: 'New York (NYC)', date: '01-Nov-2026', pax: '1', class: 'Economy' }
        ];

        for (const data of testData) {
            await FlightSearchPage.performSearch(data.origin, data.dest, data.date, data.pax, data.class);
            const resultsLoaded = await FlightSearchPage.flightResults.isDisplayed();
            expect(resultsLoaded).to.be.true;
            // Additional assertions for branding and airport codes would follow here
        }
    });

    // Test Case #2: Dynamic Date Search
    it('Verify flight search execution with dynamic future dates', async () => {
        const dynamicDate = new Date();
        dynamicDate.setDate(dynamicDate.getDate() + 15);
        const dateStr = dynamicDate.toLocaleDateString();

        await FlightSearchPage.performSearch('Mumbai (BOM)', 'New York (NYC)', dateStr, '1', 'Economy');

        const isVisible = await FlightSearchPage.flightResults.isDisplayed();
        expect(isVisible).to.be.true;
    });
});
```

---
**Note:** Ensure `.env` is configured for any environment-specific variables. Credentials or sensitive configurations must be managed via `process.env`. If utilizing authentication, store the API token/password in `.env` as `PASSWORD=your_secure_password` and access via `process.env.PASSWORD`.

