    if (value === undefined) {
      throw new Error(`CRITICAL CONFIG ERROR: Environment variable "${key}" is not defined in .env`);
    }
    return value;
  }

  public static getAppUrl(): string {
    return this.get('APP_URL');
  }

  public static getValidUsername(): string {
    return this.get('VALID_USERNAME');
  }

  public static getValidPassword(): string {
    return this.get('VALID_PASSWORD');
  }
}

