import { Page, Locator, expect } from '@playwright/test';

export abstract class BasePage {
  public readonly page: Page;

  constructor(page: Page) {
    this.page = page;
  }

  public async navigateTo(url: string): Promise<void> {
    await this.page.goto(url, { waitUntil: 'domcontentloaded' });
  }

  public async fill(locator: Locator, text: string): Promise<void> {
    await locator.waitFor({ state: 'visible' });
    await locator.fill(text);
  }

  public async click(locator: Locator): Promise<void> {
    await locator.waitFor({ state: 'visible' });
    await locator.click();
  }

  public async getElementText(locator: Locator): Promise<string> {
    await locator.waitFor({ state: 'visible' });
    const text = await locator.textContent();
    return text ? text.trim() : '';
  }

  public async isVisible(locator: Locator): Promise<boolean> {
    try {
      await locator.waitFor({ state: 'visible', timeout: 5000 });
      return await locator.isVisible();
    } catch {
      return false;
    }
  }

  public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
    await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
  }
}

import { Locator, Page, expect } from '@playwright/test';
import { BasePage } from './BasePage';
import { EnvUtils } from '../utils/envUtils';

export class LoginPage extends BasePage {
  public readonly usernameInput: Locator;
  public readonly passwordInput: Locator;
  public readonly loginButton: Locator;
  public readonly errorMessage: Locator;

  constructor(page: Page) {
    super(page);
    this.usernameInput = page.locator('input[name="username"]');
    this.passwordInput = page.locator('input[name="password"]');
    this.loginButton = page.locator('button[type="submit"]');
    this.errorMessage = page.locator('.oxd-alert-content-text');
  }

  public async navigateToLoginPage(): Promise<void> {
    const url = EnvUtils.getAppUrl();
    await this.navigateTo(url);
  }

  public async enterUsername(username: string): Promise<void> {
    await this.fill(this.usernameInput, username);
  }

  public async enterPassword(password: string): Promise<void> {
    await this.fill(this.passwordInput, password);
  }

  public async clickLogin(): Promise<void> {
    await this.click(this.loginButton);
  }

  public async getErrorMessageText(): Promise<string> {
    return await this.getElementText(this.errorMessage);
  }
}

import { Locator, Page, expect } from '@playwright/test';
import { BasePage } from './BasePage';

export class DashboardPage extends BasePage {
  public readonly dashboardHeader: Locator;

  constructor(page: Page) {
    super(page);
    this.dashboardHeader = page.locator('h6.oxd-text', { hasText: 'Dashboard' });
  }

  public async isDashboardDisplayed(): Promise<boolean> {
    return await this.isVisible(this.dashboardHeader);
  }

  public async getUrl(): Promise<string> {
    return this.page.url();
  }
}

import { Given, When, Then, Before, After, setDefaultTimeout } from '@cucumber/cucumber';
import { chromium, Browser, Page, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { DashboardPage } from '../pages/DashboardPage';
import { EnvUtils } from '../utils/envUtils';

// Set generic execution timeout to 30 seconds
setDefaultTimeout(30000);

let browser: Browser;
let page: Page;
let loginPage: LoginPage;
let dashboardPage: DashboardPage;

Before(async () => {
  // Initialize Chromium Headless Instance
  browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  page = await context.newPage();

  // Initialize Page Object Models
  loginPage = new LoginPage(page);
  dashboardPage = new DashboardPage(page);
});

After(async () => {
  if (browser) {
    await browser.close();
  }
});

Given('the user navigates to the OrangeHRM login page', async () => {
  await loginPage.navigateToLoginPage();
});

When('the user enters their valid username', async () => {
  const username = EnvUtils.getValidUsername();
  await loginPage.enterUsername(username);
});

When('the user enters their valid password', async () => {
  const password = EnvUtils.getValidPassword();
  await loginPage.enterPassword(password);
});

When('the user enters an administrative username {string}', async (username: string) => {
  await loginPage.enterUsername(username);
});

When('the user enters an incorrect password {string}', async (password: string) => {
  await loginPage.enterPassword(password);
});

When('the user clicks on the login button', async () => {
  await loginPage.clickLogin();
});

Then('the user should be successfully redirected to the dashboard', async () => {
  // Verify Dashboard elements are visible and URL has changed
  const isDashboardVisible = await dashboardPage.isDashboardDisplayed();
  expect(isDashboardVisible).toBe(true);

  const currentUrl = await dashboardPage.getUrl();
  expect(currentUrl).toContain('/dashboard/index');
});

Then('an error message displaying {string} should be visible', async (expectedError: string) => {
  const actualErrorText = await loginPage.getErrorMessageText();
  expect(actualErrorText).toBe(expectedError);
});

