import { expect, Locator, Page } from '@playwright/test';

/**
 * Abstract Base Page class serving as the foundation for all Page Objects.
 */
export abstract class BasePage {
    public readonly page: Page;

    /**
     * @param page Playwright Page context
     */
    constructor(page: Page) {
        this.page = page;
    }

    /**
     * Helper wrapper for page navigation.
     */
    public async navigateTo(url: string): Promise<void> {
        await this.page.goto(url);
    }

    /**
     * Safely retrieves inner text content of a Locator with an explicit await.
     */
    public async getText(locator: Locator): Promise<string> {
        return (await locator.textContent()) || '';
    }

    /**
     * Shared wait-for-enabled method ensuring UI ready states before interactions.
     */
    public async waitForEnabled(locator: Locator, timeout?: number): Promise<void> {
        await expect(locator).toBeEnabled({ timeout: timeout ?? 10000 });
    }
}

import { expect, Locator, Page } from '@playwright/test';
import { BasePage } from './BasePage';

/**
 * Flight Search Page Object containing locators and automation flows.
 */
export class FlightSearchPage extends BasePage {
    // Nav Headers & Action Elements
    public readonly signupButton: Locator;

    // Radio button selectors
    public readonly multiCityRadio: Locator;
    public readonly oneWayRadio: Locator;
    public readonly roundTripRadio: Locator;

    // Search Button
    public readonly searchFlightsBtn: Locator;

    // Date Fields & Result Cards
    public readonly departureDateInput: Locator;
    public readonly flightCardsList: Locator;
    public readonly flightCardDateTexts: Locator;

    constructor(page: Page) {
        super(page);

        // Element initialization with Locator priorities
        this.signupButton = this.page.getByRole('button', { name: 'SIGNUP' });

        this.multiCityRadio = this.page.getByLabel('Multi-City');
        this.oneWayRadio = this.page.getByLabel('One Way');
        this.roundTripRadio = this.page.getByLabel('Round Trip');

        this.searchFlightsBtn = this.page.getByRole('button', { name: 'Search Flights' });
        this.departureDateInput = this.page.getByPlaceholder('MMM DD, YYYY');

        this.flightCardsList = this.page.locator('.flight-card');
        this.flightCardDateTexts = this.page.locator('.flight-card .flight-date');
    }

    /**
     * Asserts the styling, font-family, and alignment of the Navigation Signup button.
     */
    public async verifySignupButtonStyling(): Promise<void> {
        await expect(this.signupButton).toBeVisible();

        // Retrieve computed CSS properties
        const borderStyle = await this.signupButton.evaluate((el) => window.getComputedStyle(el).borderStyle);
        const fontFamily = await this.signupButton.evaluate((el) => window.getComputedStyle(el).fontFamily);

        expect(borderStyle).not.toBe('none');
        expect(fontFamily).toContain('sans-serif');
    }

    /**
     * Inspects layout alignment of Multi-City relative to One Way and Round Trip elements.
     */
    public async verifyRadioButtonsAlignment(): Promise<void> {
        const multiCityBox = await this.multiCityRadio.boundingBox();
        const oneWayBox = await this.oneWayRadio.boundingBox();
        const roundTripBox = await this.roundTripRadio.boundingBox();

        if (multiCityBox && oneWayBox && roundTripBox) {
            // Verify horizontal layout alignment checks
            const midMultiCityY = multiCityBox.y + multiCityBox.height / 2;
            const midOneWayY = oneWayBox.y + oneWayBox.height / 2;
            const midRoundTripY = roundTripBox.y + roundTripBox.height / 2;

            // Layout is horizontally aligned within a 5px structural threshold
            expect(Math.abs(midMultiCityY - midOneWayY)).toBeLessThan(5);
            expect(Math.abs(midMultiCityY - midRoundTripY)).toBeLessThan(5);
        } else {
            throw new Error('Could not calculate layout dimensions for target search radio buttons.');
        }
    }

    /**
     * Verifies background color matches expected styling specifications.
     * @param expectedColorHex Hexadecimal color value (e.g., #007bff)
     */
    public async verifySearchButtonColor(expectedColorHex: string): Promise<void> {
        const actualColorRgb = await this.searchFlightsBtn.evaluate((el) => window.getComputedStyle(el).backgroundColor);

        // Convert dynamic browser color returns (rgb/rgba) and compare
        const hexVal = this.rgbToHex(actualColorRgb);
        expect(hexVal.toLowerCase()).toBe(expectedColorHex.toLowerCase());
    }

    /**
     * Asserts the placeholder values loaded on the Departure Date field.
     * @param expectedPlaceholder string
     */
    public async verifyDepartureDatePlaceholder(expectedPlaceholder: string): Promise<void> {
        const actualPlaceholder = await this.departureDateInput.getAttribute('placeholder');
        expect(actualPlaceholder).toBe(expectedPlaceholder);
    }

    /**
     * Performs a standard search to display flight cards.
     */
    public async performFlightSearch(): Promise<void> {
        await this.searchFlightsBtn.click();
        await this.page.waitForLoadState('networkidle');
    }

    /**
     * Validates card formatting and text color rules on Flight Results cards.
     * @param expectedHexColor CSS Text Hex color code
     */
    public async verifyResultCardsDateColors(expectedHexColor: string): Promise<void> {
        await this.flightCardsList.first().waitFor({ state: 'visible' });
        const count = await this.flightCardDateTexts.count();
        expect(count).toBeGreaterThan(0);

        for (let i = 0; i < count; i++) {
            const dateElement = this.flightCardDateTexts.nth(i);
            const actualColorRgb = await dateElement.evaluate((el) => window.getComputedStyle(el).color);
            const actualHex = this.rgbToHex(actualColorRgb);
            expect(actualHex.toLowerCase()).toBe(expectedHexColor.toLowerCase());
        }
    }

    /**
     * Helper to map rgb elements into standard HEX format
     */
    private rgbToHex(rgbStr: string): string {
        const match = rgbStr.match(/^rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*(\d+(?:\.\d+)?))?\)$/);
        if (!match) return rgbStr;

        const r = parseInt(match[1]).toString(16).padStart(2, '0');
        const g = parseInt(match[2]).toString(16).padStart(2, '0');
        const b = parseInt(match[3]).toString(16).padStart(2, '0');

        return `#${r}${g}${b}`;
    }
}

