import { test, expect, Page } from '@playwright/test';
import { FlightSearchPage } from '../pages/FlightSearchPage';
import { EnvUtils } from '../utils/envUtils';
import * as testData from '../data/testData.json';

test.describe('Flight Search Page Interface Compliance Suite', () => {

    test.beforeEach(async ({ page }) => {
        // Navigate globally to Base URL before each test implementation
        await page.goto(EnvUtils.BASE_URL);
    });

    // PARAMETERIZED EXECUTION: Test Case #1
    for (const dataset of testData.testCase1Data) {
        test(`${dataset.testCaseId} - ${dataset.scenarioTitle} (${dataset.targetState})`, async ({ page }, testInfo) => {
            // Apply customized screen sizing configured per test dataset
            await page.setViewportSize({ 
                width: dataset.viewport.width, 
                height: dataset.viewport.height 
            });

            const searchPage = new FlightSearchPage(page);

            // Step 1: Navigate to the Flight Search page has completed in the beforeEach hook.

            // Step 2: Inspect layout alignment of 'Multi-City' radio button.
            await searchPage.verifyRadioButtonsAlignment();

            // Set state simulation according to specifications
            if (dataset.targetState === 'Hovered') {
                await searchPage.multiCityRadio.hover();
            } else if (dataset.targetState === 'Focused') {
                await searchPage.multiCityRadio.focus();
            }

            // Step 3: Observe background color of 'Search Flights' button and compare with specifications.
            await searchPage.verifySearchButtonColor(dataset.expectedBrandColor);

            // Step 4: Observe styling, font, and border layout of 'SIGNUP' navigation option.
            await searchPage.verifySignupButtonStyling();
        });
    }

    // PARAMETERIZED EXECUTION: Test Case #2
    for (const dataset of testData.testCase2Data) {
        test(`${dataset.testCaseId} - ${dataset.scenarioTitle}`, async ({ page }, testInfo) => {
            const searchPage = new FlightSearchPage(page);

            // Step 1: Navigate to Flight Search page has completed in the beforeEach hook.

            // Step 2: Locate Departure date input and verify prefilled placeholder formatting rules.
            await searchPage.verifyDepartureDatePlaceholder(dataset.placeholderValue);

            // Step 3: Perform search operation to populate flight records on search results page.
            await searchPage.performFlightSearch();

            // Step 4: Inspect card displays to assert date element style uniformity.
            await searchPage.verifyResultCardsDateColors(dataset.cardTextColor);
        });
    }
});

