import { setWorldConstructor, World, IWorldOptions } from '@cucumber/cucumber';
import { Browser, BrowserContext, Page } from '@playwright/test';
import { FlightSearchPage } from '../../pages/FlightSearchPage';

export interface ICustomWorld extends World {
    browser?: Browser;
    context?: BrowserContext;
    page?: Page;
    flightSearchPage?: FlightSearchPage;
}

export class CustomWorld extends World implements ICustomWorld {
    public browser?: Browser;
    public context?: BrowserContext;
    public page?: Page;
    public flightSearchPage?: FlightSearchPage;

    constructor(options: IWorldOptions) {
        super(options);
    }
}

setWorldConstructor(CustomWorld);

import { BeforeAll, AfterAll, Before, After, Status } from '@cucumber/cucumber';
import { chromium, Browser } from '@playwright/test';
import { CustomWorld } from './custom-world';
import { FlightSearchPage } from '../../pages/FlightSearchPage';

let browser: Browser;

BeforeAll(async () => {
    browser = await chromium.launch({ headless: true });
});

AfterAll(async () => {
    await browser.close();
});

Before(async function (this: CustomWorld) {
    this.browser = browser;
    this.context = await this.browser.newContext();
    this.page = await this.context.newPage();
    this.flightSearchPage = new FlightSearchPage(this.page);
});

After(async function (this: CustomWorld, scenario) {
    if (scenario.result?.status === Status.FAILED && this.page) {
        const screenshot = await this.page.screenshot({
            path: `reports/screenshots/${scenario.pickle.name.replace(/\s+/g, '_')}_failed.png`,
            fullPage: true,
        });
        this.attach(screenshot, 'image/png');
    }
    await this.page?.close();
    await this.context?.close();
});

import { Given, When, Then } from '@cucumber/cucumber';
import { CustomWorld } from '../support/custom-world';
import { EnvUtils } from '../../utils/envUtils';

Given('I navigate to the Flight Search page', async function (this: CustomWorld) {
    if (!this.flightSearchPage) throw new Error('FlightSearchPage not initialized');
    await this.flightSearchPage.navigateTo(EnvUtils.BASE_URL);
});

Given('I set the viewport size to width {int} and height {int}', async function (this: CustomWorld, width: number, height: number) {
    if (!this.page) throw new Error('Page context is missing');
    await this.page.setViewportSize({ width, height });
});

When('I inspect the layout alignment of the "Multi-City" radio button', async function (this: CustomWorld) {
    if (!this.flightSearchPage) throw new Error('FlightSearchPage not initialized');
    await this.flightSearchPage.verifyRadioButtonsAlignment();
});

When('I simulate target state {string} on the "Multi-City" radio button', async function (this: CustomWorld, targetState: string) {
    if (!this.flightSearchPage) throw new Error('FlightSearchPage not initialized');
    if (targetState === 'Hovered') {
        await this.flightSearchPage.multiCityRadio.hover();
    } else if (targetState === 'Focused') {
        await this.flightSearchPage.multiCityRadio.focus();
    }
});

Then('the "Search Flights" button should have the background color {string}', async function (this: CustomWorld, expectedColor: string) {
    if (!this.flightSearchPage) throw new Error('FlightSearchPage not initialized');
    await this.flightSearchPage.verifySearchButtonColor(expectedColor);
});

Then('the "SIGNUP" navigation option should meet styling, font, and border specifications', async function (this: CustomWorld) {
    if (!this.flightSearchPage) throw new Error('FlightSearchPage not initialized');
    await this.flightSearchPage.verifySignupButtonStyling();
});

Given('the departure date field displays the placeholder {string}', async function (this: CustomWorld, placeholderValue: string) {
    if (!this.flightSearchPage) throw new Error('FlightSearchPage not initialized');
    await this.flightSearchPage.verifyDepartureDatePlaceholder(placeholderValue);
});

When('I perform a flight search', async function (this: CustomWorld) {
    if (!this.flightSearchPage) throw new Error('FlightSearchPage not initialized');
    await this.flightSearchPage.performFlightSearch();
});

Then('all displayed flight cards should have date text formatted with color {string}', async function (this: CustomWorld, cardTextColor: string) {
    if (!this.flightSearchPage) throw new Error('FlightSearchPage not initialized');
    await this.flightSearchPage.verifyResultCardsDateColors(cardTextColor);
});

