import org.testng.annotations.*;
import com.qa.pages.LandingAuthenticationPagePage;
import com.qa.pages.ApplicationDashboardNavigationPage;
import com.qa.pages.WorkflowDetailsActionViewPage;

public class UploadvideokdkAutomatedFlowTest {
    private Playwright playwright;
    private Browser browser;
    private BrowserContext context;
    private Page page;

    @BeforeClass
    public void setUp() {
        playwright = Playwright.create();
        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(true));
        context = browser.newContext(new Browser.NewContextOptions().setViewportSize(1280, 800));
        page = context.newPage();
    }

    @Test
    public void testUploadvideokdkAutomatedFlowWorkflow() {
        LandingAuthenticationPagePage landingauthenticationpagePage = new LandingAuthenticationPagePage(page);
        ApplicationDashboardNavigationPage applicationdashboardnavigationPage = new ApplicationDashboardNavigationPage(page);
        WorkflowDetailsActionViewPage workflowdetailsactionviewPage = new WorkflowDetailsActionViewPage(page);

        // Navigate to entry URL
        landingauthenticationpagePage.open();

        // Step 1: Verify Application Home Page
        Assert.assertTrue(landingauthenticationpagePage.verify_application_home_page());

        // Step 2: Fill Username / Mobile Number Field
        landingauthenticationpagePage.fill_username___mobile_number_field("9876543210");

        // Step 3: Fill Password Field
        landingauthenticationpagePage.fill_password_field("SecretPassword123!");

        // Step 4: Click Login to Dashboard Button
        landingauthenticationpagePage.click_login_to_dashboard_button();

        // Step 5: Click Main Module Navigation Menu
        applicationdashboardnavigationPage.click_main_module_navigation_menu();

        // Step 6: Click Action Trigger Button
        workflowdetailsactionviewPage.click_action_trigger_button();

        // Step 7: Verify Workflow Verification View
        Assert.assertTrue(workflowdetailsactionviewPage.verify_workflow_verification_view());
    }

    @AfterClass
    public void tearDown() {
        if (browser != null) browser.close();
        if (playwright != null) playwright.close();
    }
}

